private theorem coeff_m3Quadratic (q : ℚ) (σ : FactorType) :
    coeffAt q (childProd (otherChildren 1 m3Quadratic)) σ =
      if σ = (1,1) ::ₘ {(1,2)} then 1 else 0

private theorem coeff_m3Split (q : ℚ) (σ : FactorType) :
